import java.util.*;

class Solution {
    public int reverseNumber(int n) {
        int rev = 0;
        while (n > 0) {
            rev = rev * 10 + n % 10;         // push last digit onto rev
            n /= 10;                         // drop last digit
        }
        return rev;
    }
}

